{
    "sla_rules": [
        {
            "rule_id": "RULE_001",
            "metric": "DaysToHire",
            "threshold": 30.0,
            "threshold_operator": "<",
            "penalty_amount": 500,
            "penalty_type": "monetary",
            "penalty_percentage": 10,
            "description": "10% penalty if DaysToHire is less than TargetDaysToHire",
            "applicable_period": "monthly"
        }
    ],
    "violation_conditions": [
        {
            "metric": "DaysToHire",
            "condition": "DaysToHire < TargetDaysToHire",
            "penalty_rule": "10% penalty if hiring process is faster than target days"
        }
    ],
    "sql_query": "SELECT IncidentID, CASE WHEN DaysToHire < TargetDaysToHire THEN 0.1 * 10000 ELSE 0 END AS Penalty FROM incidents_trainer_hiring ORDER BY IncidentID",
    "data_fields_required": ["IncidentID", "DaysToHire", "TargetDaysToHire"],
    "monthly_service_fee": 10000,
    "max_monthly_penalty_percentage": 10
}
